// @vitest-environment jsdom
import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import { beforeAll, describe, expect, it } from 'vitest';
import { Game } from '../game/Game';
import { InputManager } from '../input/InputManager';
import { AppUI } from '../ui';
import { applyMatchOutcome, profileSummary, settingsToUi } from './ProfileStore';
import { SaveManager } from './SaveManager';
import type { StorageLike } from './SaveManager';

const STEP = 1 / 60;

class MemoryStorage implements StorageLike {
  private readonly map = new Map<string, string>();
  getItem(key: string): string | null {
    return this.map.get(key) ?? null;
  }
  setItem(key: string, value: string): void {
    this.map.set(key, value);
  }
  removeItem(key: string): void {
    this.map.delete(key);
  }
}

beforeAll(async () => {
  await RAPIER.init();
});

describe('match progress survives a reload', () => {
  it('stores the finished match and shows it on the profile screen', async () => {
    const storage = new MemoryStorage();
    const saves = new SaveManager(storage);
    let profile = saves.load();
    expect(profile.statistics.matchesPlayed).toBe(0);

    const overlay = document.createElement('div');
    document.body.append(overlay);
    const input = new InputManager({});
    const camera = new THREE.PerspectiveCamera(60, 1.5, 0.1, 400);
    const game = await Game.create({
      renderer: {} as unknown as THREE.WebGLRenderer,
      camera,
      input,
      overlayRoot: overlay,
      courseId: 'green-hills',
      holeCount: 1,
      humanCount: 1,
      botCount: 0,
      controlScheme: 'hold-to-charge',
      playerName: profile.displayName,
      playerRating: profile.rating,
      ballStyleId: profile.cosmetics.ballId,
      // Exactly the wiring main.ts installs: reward -> profile -> save file.
      onMatchComplete: (outcome) => {
        profile = applyMatchOutcome(profile, outcome);
        saves.save(profile);
      },
    });

    const results = overlay.querySelector<HTMLElement>('.match-results');
    const status = overlay.querySelector<HTMLElement>('.hud-status');
    let charge = 0;
    for (let frame = 0; frame < 30000; frame += 1) {
      if (results?.hidden === false) break;
      if (charge > 0) {
        charge += 1;
        if (charge > 30) {
          window.dispatchEvent(new KeyboardEvent('keyup', { code: 'Space' }));
          charge = 0;
        }
      } else if (status?.dataset.ready === 'true') {
        window.dispatchEvent(new KeyboardEvent('keydown', { code: 'Space' }));
        charge = 1;
      }
      game.frame(STEP);
      input.endFrame();
    }
    expect(results?.hidden).toBe(false);

    game.dispose();
    input.dispose();
    overlay.remove();

    const reloaded = new SaveManager(storage).load();
    expect(reloaded.statistics.matchesPlayed).toBe(1);
    expect(reloaded.statistics.matchesWon).toBe(1);
    expect(reloaded.statistics.holesPlayed).toBe(1);
    expect(reloaded.statistics.holesCompleted).toBe(1);
    expect(reloaded.statistics.totalStrokes).toBeGreaterThan(0);
    expect(reloaded.statistics.bestRoundStrokes).not.toBeNull();
    expect(reloaded.progression.xp).toBeGreaterThanOrEqual(100);

    const summary = profileSummary(reloaded);
    const root = document.createElement('div');
    new AppUI(root, {}, { profile: summary, settings: settingsToUi(reloaded.settings) });
    root.querySelector<HTMLElement>('[data-nav="profile"]')?.click();
    const text = root.textContent ?? '';
    expect(text).toContain('Rating ' + String(summary.rating));
    expect(text).toContain(String(summary.xp) + ' / ' + String(summary.xpNext) + ' XP');
    expect(text).toContain('Matches');
    expect(text).toContain('100%');
  }, 120000);
});
